mapper.select:
SELECT l.id, l.operator, l.operator_id, l.action, l.target_type, l.target_id, l.target_name, l.description, l.ip, l.user_agent, l.status, l.error_message, l.created_at FROM system_logs l
AND l.operator LIKE CONCAT('%', #{operator}, '%')
AND l.action = #{action}
AND l.target_type = #{targetType}
AND l.created_at >= #{startTime}
AND l.created_at <= #{endTime}
AND l.status = #{status}
ORDER BY l.created_at DESC

SELECT COUNT(*)
FROM system_logs
WHERE operator_id = #{operatorId}

SELECT COUNT(*)
FROM system_logs
WHERE created_at >= #{startTime} AND created_at <= #{endTime}
